insert into public.training_scenarios_v22(stable_key,title,scenario_type,role_focus,intro,prompt,decisions,debrief,visuals,media,sources) values
('v22:dlspp-common','DL-SPP comune: dal rischio al piano d’azione','tabletop','datore di lavoro SPP','Un rischio è noto, le misure esistono sulla carta ma le segnalazioni mostrano che non funzionano in modo stabile.','Rivaluta esposizione, cause, gerarchia delle misure, responsabilità, formazione e verifica di efficacia.','[{"choice":"Riprogetto la barriera debole e definisco un indicatore di efficacia","effect":"Gestione ciclica del rischio"},{"choice":"Rinforzo le istruzioni agli operatori","effect":"Possibile mancata azione sulla causa"}]'::jsonb,'{"questions":["Quale barriera è debole?","Quale misura viene prima del comportamento?","Come verifichi l’efficacia?"]}'::jsonb,'[{"asset":"idea-dvr-reading.svg"},{"asset":"idea-safety-system.svg"},{"asset":"idea-risk-cycle.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - valutazione e gestione del rischio","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb),
('v22:dlspp-update','DL-SPP aggiornamento: near miss e management of change','incident_analysis','datore di lavoro SPP','Un quasi incidente evidenzia che processo, persone o attrezzature sono cambiati più velocemente delle misure di prevenzione.','Ricostruisci il near miss, individua il cambiamento non governato e chiudi il ciclo con una misura e una verifica sul campo.','[{"choice":"Tratto il near miss come segnale del sistema e aggiorno misure/processo","effect":"Apprendimento organizzativo"},{"choice":"Rinforzo la regola violata","effect":"Rischio di attribuire tutto all’errore umano"}]'::jsonb,'{"questions":["Quale cambiamento ha aperto il gap?","Quale barriera doveva intercettarlo?","Come eviti la ricorrenza?"]}'::jsonb,'[{"asset":"idea-inspection-flow.svg"},{"asset":"idea-risk-cycle.svg"}]'::jsonb,'[{"kind":"video_hub","title":"Napo - imparare dagli incidenti","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb),
('v22:dlspp-agri','DL-SPP agricoltura: mezzi, animali, caldo e lavoro isolato','hazard_spotting','datore di lavoro SPP agricoltura','Una giornata combina trattore, attrezzature, caldo, lavoratori dispersi e possibile interazione con animali.','Progetta la giornata definendo percorsi, competenze, comunicazioni, pause/calore, emergenza e condizioni che impediscono l’avvio.','[{"choice":"Pianifico attività e sequenze in base a terreno, mezzi, meteo e disponibilità di supporto","effect":"Rischi agricoli trattati insieme"},{"choice":"Gestisco ogni rischio separatamente durante il lavoro","effect":"Interazioni e cambiamenti restano deboli"}]'::jsonb,'{"questions":["Come cambia il piano con caldo estremo?","Quali lavori isolati richiedono contatto programmato?","Quale rischio di ribaltamento controlli prima?"]}'::jsonb,'[{"asset":"idea-green-safearea.svg"},{"asset":"idea-heat-stress.svg"},{"asset":"idea-inspection-flow.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - sicurezza in agricoltura","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb),
('v22:dlspp-pesca','DL-SPP pesca: ponte bagnato, verricelli, mare e lavoro di squadra','tabletop','datore di lavoro SPP pesca','A bordo, movimento dell’imbarcazione, superfici bagnate, attrezzature di tiro, carichi e condizioni meteo interagiscono continuamente.','Organizza una fase di pesca definendo zone, comunicazioni, movimentazione, attrezzature, DPI, igiene e criteri di sospensione.','[{"choice":"Definisco ruoli/zone e limiti operativi prima della fase, rivalutando al cambiare del mare","effect":"Sistema adattivo"},{"choice":"Affido il coordinamento all’esperienza dell’equipaggio","effect":"Regole implicite e variabili"}]'::jsonb,'{"questions":["Quali zone vanno tenute libere durante il tiro?","Quando il meteo cambia la decisione?","Come gestisci contaminazione/tagli durante lavorazione del pescato?"]}'::jsonb,'[{"asset":"idea-risk-cycle.svg"},{"asset":"video-safe-moves.svg"},{"asset":"idea-bio-chain.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - buone pratiche nella pesca","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/terza-missione/applicativi-per-la-salute-e-la-sicurezza-sul-lavoro/buone-pratiche/pesca.html"},{"kind":"reference","title":"INAIL - agenti biologici nella pesca","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/agenti-biologici/Ambienti-di-lavoro.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/terza-missione/applicativi-per-la-salute-e-la-sicurezza-sul-lavoro/buone-pratiche/pesca.html"}]'::jsonb),
('v22:dlspp-construction','DL-SPP costruzioni: fase di cantiere, scavo, quota e mezzi','tabletop','datore di lavoro SPP costruzioni','Una fase di cantiere combina scavo, mezzi, lavoro in quota e più imprese nella stessa area.','Scomponi la fase, individua interferenze, protezioni collettive, accessi, mezzi, sequenza e autorizzazione alla partenza.','[{"choice":"Separo attività incompatibili e verifico protezioni prima dell’avvio","effect":"Rischio ridotto nella pianificazione"},{"choice":"Lascio il coordinamento alle riunioni giornaliere sul posto","effect":"Interferenze risolte troppo tardi"}]'::jsonb,'{"questions":["Quali fasi non possono sovrapporsi?","Quale protezione collettiva viene prima?","Chi autorizza una variazione?"]}'::jsonb,'[{"asset":"idea-duvri.svg"},{"asset":"idea-working-height-safe.svg"},{"asset":"idea-inspection-flow.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - cantieristica","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/cantieristica.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/cantieristica.html"}]'::jsonb),
('v22:dlspp-chemical','DL-SPP chimico-petrolchimico: contenimento, esposizione e incompatibilità','tabletop','datore di lavoro SPP chimico-petrolchimico','Una modifica di processo introduce una sostanza/miscela nuova e una diversa sequenza di travaso.','Prima dell’avvio, verifica SDS/classificazione, sostituzione, quantità, contenimento, ventilazione, incompatibilità, esposizione e risposta all’emergenza.','[{"choice":"Rivaluto processo e sostanza prima dell’uso, minimizzando quantità ed esposizione","effect":"Prevenzione integrata"},{"choice":"Aggiungo DPI coerenti con la nuova SDS e procedo","effect":"Il DPI non sostituisce misure tecniche/organizzative"}]'::jsonb,'{"questions":["Quale informazione prendi dalla SDS?","Cosa può essere sostituito o contenuto?","Come gestisci più agenti contemporaneamente?"]}'::jsonb,'[{"asset":"idea-risk-cycle.svg"},{"asset":"idea-dpi-hierarchy.svg"},{"asset":"video-chemicals.svg"}]'::jsonb,'[{"kind":"reference","title":"INAIL - Agenti chimici","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/agenti-chimici.html"},{"kind":"reference","title":"INAIL - Misure di prevenzione e protezione rischio chimico","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/agenti-chimici/misure-di-prevenzione-e-protezione.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/agenti-chimici.html"}]'::jsonb)
on conflict(stable_key) do update set title=excluded.title,scenario_type=excluded.scenario_type,role_focus=excluded.role_focus,intro=excluded.intro,prompt=excluded.prompt,decisions=excluded.decisions,debrief=excluded.debrief,visuals=excluded.visuals,media=excluded.media,sources=excluded.sources,active=true,updated_at=now();

insert into public.practice_labs_v22(stable_key,title,lab_type,objective,briefing,steps,checklist,critical_errors,stop_conditions,media,sources,requires_physical_validation) values
('v22:dlspp-common-lab','DL-SPP comune: action plan su rischio reale','digital','Portare un rischio dal DVR a un piano di azione verificabile sul campo.','Scegliere un rischio reale non sensibile o un caso simulato.','["descrivi attività/esposizione","mappa controlli esistenti","identifica barriera debole","genera misure secondo gerarchia","scegli owner/risorse/scadenza","definisci indicatore","fai verifica sul campo"]'::jsonb,'["esposizione","barriere","gerarchia","owner","risorse","scadenza","indicatore"]'::jsonb,'["azione generica","nessun responsabile","DPI come unica misura senza motivazione","chiusura solo documentale"]'::jsonb,'["rischio residuo non controllabile"]'::jsonb,'[{"kind":"video_hub","title":"Napo - gestione del rischio","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:dlspp-update-lab','DL-SPP aggiornamento: near miss → cambiamento','digital','Usare un evento o cambiamento per riesaminare il sistema di prevenzione.','Partire da near miss reale anonimizzato o scenario fornito.','["ricostruisci timeline","trova cambiamento","identifica barriera fallita","scegli correzione","aggiorna formazione/procedura se serve","verifica sul campo","condividi lezione"]'::jsonb,'["timeline","cambiamento","barriera","azione","competenza","verifica"]'::jsonb,'["attribuire causa a distrazione","aggiornare solo documento","nessun follow-up"]'::jsonb,'["barriera critica ancora degradata"]'::jsonb,'[{"kind":"video_hub","title":"Napo - imparare dagli incidenti","url":"https://www.napofilm.net/it"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/"}]'::jsonb,false),
('v22:dlspp-agri-lab','DL-SPP agricoltura: piano operativo della giornata','hybrid','Integrare mezzi, terreno, caldo, persone, animali e lavoro isolato in un unico pre-start.','Applicare a una giornata reale o a una mappa dell’azienda.','["mappa lavorazioni","segna mezzi e percorsi","valuta meteo/calore","identifica lavori isolati","verifica competenze/abilitazioni","definisci comunicazioni","imposta stop condition","debriefing fine giornata"]'::jsonb,'["mezzi","terreno","meteo","lavoro isolato","competenze","comunicazioni","stop"]'::jsonb,'["programmare ogni attività separatamente","nessun controllo contatto lavoratore isolato","ignorare effetto meteo su stabilità/calore"]'::jsonb,'["meteo incompatibile","mezzo non idoneo","supporto emergenza non disponibile"]'::jsonb,'[{"kind":"reference","title":"INAIL - sicurezza in agricoltura","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/agricoltura.html"}]'::jsonb,false),
('v22:dlspp-pesca-lab','DL-SPP pesca: walkthrough di una fase a bordo','hybrid','Analizzare una fase di pesca considerando simultaneamente movimento nave, attrezzature, carichi, bagnato, biologico e comunicazioni.','Usare planimetria/foto dell’imbarcazione o walkthrough in condizioni sicure e senza attività pericolose in corso.','["mappa zone e percorsi","segna attrezzature in movimento","identifica punti scivolosi/schiacciamento","analizza movimentazione carichi","verifica igiene/tagli biologico","definisci comunicazioni","imposta limiti meteo/operativi","debriefing"]'::jsonb,'["zone","movimento","scivolamento","carichi","biologico","comunicazioni","meteo"]'::jsonb,'["restare in zona di tiro","comunicazioni implicite","nessun piano per cambio meteo","contatto non protetto con materiale biologico"]'::jsonb,'["mare/meteo incompatibile","attrezzatura non controllata","comunicazione non affidabile"]'::jsonb,'[{"kind":"reference","title":"INAIL - buone pratiche pesca","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/terza-missione/applicativi-per-la-salute-e-la-sicurezza-sul-lavoro/buone-pratiche/pesca.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/terza-missione/applicativi-per-la-salute-e-la-sicurezza-sul-lavoro/buone-pratiche/pesca.html"}]'::jsonb,false),
('v22:dlspp-construction-lab','DL-SPP costruzioni: pre-start di fase','hybrid','Governare una fase di cantiere prima dell’avvio collegando piano, protezioni, mezzi, accessi e imprese.','Usare planimetria e sequenza reali o scenario equivalente.','["scomponi fase","mappa imprese/mezzi","individua quota/scavo/interferenze","scegli protezioni collettive","definisci viabilità/accessi","briefing responsabili","walk-around","autorizza avvio","riesamina a variazione"]'::jsonb,'["fase","interferenze","protezioni","viabilità","ruoli","walk-around","variazioni"]'::jsonb,'["affidarsi solo a DPI","iniziare con protezione collettiva incompleta","variazione gestita sul momento"]'::jsonb,'["protezione critica assente","scavo/terreno instabile","interferenza non chiusa"]'::jsonb,'[{"kind":"reference","title":"INAIL - cantieristica","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/cantieristica.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/ricerca-e-tecnologia/it/ambiti-di-ricerca/area-sicurezza-sul-lavoro/cantieristica.html"}]'::jsonb,false),
('v22:dlspp-chemical-lab','DL-SPP chimico: SDS, sostituzione e spill tabletop','hybrid','Valutare un nuovo agente/processo e testare la risposta a una perdita simulata senza usare sostanze pericolose.','Usare SDS reali non riservate o schede didattiche; lo spill è simulato con materiale innocuo.','["leggi identificazione/pericoli SDS","mappa vie di esposizione","verifica sostituzione/quantità","controlla ventilazione/contenimento","valuta incompatibilità/stoccaggio","scegli DPI residuo","simula spill e isolamento","debriefing emergenza"]'::jsonb,'["SDS","esposizione","sostituzione","quantità","contenimento","incompatibilità","DPI","emergenza"]'::jsonb,'["partire dai DPI","mescolare agenti senza analisi incompatibilità","pulire perdita senza procedura","ignorare esposizione cutanea"]'::jsonb,'["SDS assente/incoerente","contenimento/ventilazione non disponibili","sostanza o quantità fuori scenario valutato"]'::jsonb,'[{"kind":"reference","title":"INAIL - Agenti chimici","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/agenti-chimici.html"},{"kind":"reference","title":"INAIL - misure prevenzione/protezione","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/agenti-chimici/misure-di-prevenzione-e-protezione.html"}]'::jsonb,'[{"authority":"INAIL","url":"https://www.inail.it/portale/prevenzione-e-sicurezza/it/come-fare-per/conoscere-il-rischio/agenti-chimici.html"}]'::jsonb,false)
on conflict(stable_key) do update set title=excluded.title,lab_type=excluded.lab_type,objective=excluded.objective,briefing=excluded.briefing,steps=excluded.steps,checklist=excluded.checklist,critical_errors=excluded.critical_errors,stop_conditions=excluded.stop_conditions,media=excluded.media,sources=excluded.sources,requires_physical_validation=excluded.requires_physical_validation,active=true,updated_at=now();

with map(course_key,scenario_key,lab_key,is_update) as (values
('dl_spp_comune','v22:dlspp-common','v22:dlspp-common-lab',false),('agg_dl_spp','v22:dlspp-update','v22:dlspp-update-lab',true),
('dl_spp_agri','v22:dlspp-agri','v22:dlspp-agri-lab',false),('dl_spp_pesca','v22:dlspp-pesca','v22:dlspp-pesca-lab',false),
('dl_spp_costruzioni','v22:dlspp-construction','v22:dlspp-construction-lab',false),('dl_spp_chimico','v22:dlspp-chemical','v22:dlspp-chemical-lab',false)
