insert into public.course_scenarios_v22(course_id,scenario_id,position,required,context)
select c.id,s.id,2,true,jsonb_build_object('assigned_by','v22_006','specific',true,'dl_spp_specific',true,'update_course',m.is_update)
from map m join public.courses c on c.stable_key=m.course_key join public.training_scenarios_v22 s on s.stable_key=m.scenario_key
where c.active and coalesce(c.metadata->>'freeze_scope','')=''
on conflict(course_id,scenario_id) do update set position=excluded.position,required=true,context=excluded.context;
with map(course_key,scenario_key,lab_key,is_update) as (values
('dl_spp_comune','v22:dlspp-common','v22:dlspp-common-lab',false),('agg_dl_spp','v22:dlspp-update','v22:dlspp-update-lab',true),
('dl_spp_agri','v22:dlspp-agri','v22:dlspp-agri-lab',false),('dl_spp_pesca','v22:dlspp-pesca','v22:dlspp-pesca-lab',false),
('dl_spp_costruzioni','v22:dlspp-construction','v22:dlspp-construction-lab',false),('dl_spp_chimico','v22:dlspp-chemical','v22:dlspp-chemical-lab',false)
)
insert into public.course_practice_labs_v22(course_id,practice_lab_id,position,required,context)
select c.id,l.id,2,true,jsonb_build_object('assigned_by','v22_006','specific',true,'dl_spp_specific',true,'update_course',m.is_update)
from map m join public.courses c on c.stable_key=m.course_key join public.practice_labs_v22 l on l.stable_key=m.lab_key
where c.active and coalesce(c.metadata->>'freeze_scope','')=''
on conflict(course_id,practice_lab_id) do update set position=excluded.position,required=true,context=excluded.context;
